42	// Shared by WorkspaceInfo and PipeInfo
43	struct CrossCoreCopyInfo {
44	  std::string copy_stmt_name;
45	  CopyDirection direction; // UbToL1 / L0cToUb
46	  std::string src_buffer_name;
47	  std::string dst_buffer_name;
48	  std::string dtype_str;           // dst dtype
49	  std::vector<std::string> params; // template params (parsed, UbToL1 swapped)
50	  Array<PrimExpr> shapes;          // workspace shapes (C-core dimensions)
51	
52	  // runtime args from ascend.cc virtual_channel
53	  int src_M = 0, src_N = 0;
54	  int dst_M = 0, dst_N = 0;
55	
56	  // C-core element count
57	  int64_t per_block_ele_nums = 0;
