60	struct CopyGlobalContext {
61	  // Maps workspace name to the corresponding detailed workspace information
62	  std::map<std::string, WorkspaceInfo> workspace_map_;
63	  // Tracks the total number of existing workspaces
64	  size_t workspace_num_ = 0;
65	  // Maps source buffer name to the associated workspace name
66	  std::unordered_map<std::string, std::string> src_to_workspace_map_;
67	  // Maps destination buffer name to the associated workspace name
68	  std::unordered_map<std::string, std::string> dst_to_workspace_map_;
69	  // Maps destination buffer name to its corresponding access Call object
70	  std::unordered_map<std::string, Call> dst_to_access_map_;
71	  // Stores the set of all buffers that are currently being tracked
72	  std::unordered_set<std::string> tracked_buffers_;
73	  // Maps source buffer name to its corresponding destination buffer name
74	  std::unordered_map<std::string, std::string> src_to_dst_map_;
75	  // Maps destination buffer name to its corresponding scope information
76	  std::unordered_map<std::string, DstBufferScope> dst_to_scope_map_;
77	  // Core meta info for vid offset calculation (threads=2 scenario)
78	  CoreMetaInfo core_meta_info_;
79	  // UB buffers that skipped VidReduction (from PrimFunc attrs)
80	  std::unordered_set<std::string> buffers_skip_vid_reduction_;
81	  // Buffer shapes (from PrimFunc attrs)
82	  std::unordered_map<std::string, Array<PrimExpr>> buffer_shapes_;
83	  // PTO pipe metadata: maps dst buffer name to pipe info for deferred pop
84	  // emission
85	  struct PipeInfo {
86	    int flag_id;         // pipe flag token
87	    int dir_type;        // 1=C2V, 2=V2C
88	    int slot_size;       // max(src_elems, dst_elems) * dtype_bytes
89	    int slot_num;        // 1
90	    std::string pipe_id; // "pipe_X_V2C" or "pipe_X_C2V"
91	    std::string op_name; // "copy_pipe_to_l1" or "copy_pipe_to_ub"
92	    std::string dtype_str;
93	    int src_M_val;
94	    int src_N_val;
95	    int dst_M_val;
96	    int dst_N_val;
97	    int split_axis = 1; // 0=TILE_NO_SPLIT, 1=TILE_UP_DOWN, 2=TILE_LEFT_RIGHT
98	    std::string workspace_name;
99	    bool has_tmp = false;
100	    int tmp_M_val = 0;
101	    int tmp_N_val = 0;
102	  };
103	  std::unordered_map<std::string, PipeInfo> pipe_info_map_;
104	};
