106	class CopyInfoCollector : public StmtExprVisitor {
107	private:
108	  CopyGlobalContext context_;
109	  bool pto_use_pipe_;
110	  std::string platform_;
111	  bool needs_gm_workspace_;
112	  int pipe_flag_id_counter_ = 0; // FlagID starts from 0
113	
114	  std::unordered_set<std::string> target_copy_stmts_ = {"copy_ub_to_l1",
115	                                                        "copy_l0c_to_ub"};
116	  std::unordered_map<std::string, DstBufferScope> scope_table_ = {
117	      {"copy_ub_to_l1", DstBufferScope::L1},
118	      {"copy_l0c_to_ub", DstBufferScope::Ub}};
119	
120	public:
121	  static const std::unordered_map<std::string, DataType> type_map_;
122	
123	  const CopyGlobalContext &GetCopyGlobalContext() const { return context_; }
124	
125	  explicit CopyInfoCollector(
126	      const std::unordered_set<std::string> &target_copy_stmts = {},
127	      const std::unordered_map<std::string, DstBufferScope> &scope_table = {},
128	      bool pto_use_pipe = false, const std::string &platform = "A3")
129	      : platform_(platform), needs_gm_workspace_(false) {
130	    if (!target_copy_stmts.empty()) {
131	      this->target_copy_stmts_ = target_copy_stmts;
132	    }
133	    if (!scope_table.empty()) {
134	      this->scope_table_ = scope_table;
135	    }
136	    this->pto_use_pipe_ = pto_use_pipe;
137	    this->needs_gm_workspace_ = (platform != "A5");
138	  }
139	
140	  void SetSkipBuffers(const std::unordered_set<std::string> &skip_buffers) {
141	    context_.buffers_skip_vid_reduction_ = skip_buffers;
142	  }
143	
144	  void SetBufferShapes(
145	      const std::unordered_map<std::string, Array<PrimExpr>> &shapes) {
146	    context_.buffer_shapes_ = shapes;
147	  }
148	
149	  DataType ConvertStringToDataType(const std::string &type_str) {
150	    auto it = type_map_.find(type_str);
151	
152	    ICHECK(it != type_map_.end())
153	        << "[Error]<WorkspaceReduction>: Not supported type: " << type_str
154	        << ", maybe you need to update type_map_.";
155	
156	    return it->second;
157	  }
158	
159	  std::string IsTargetCopyExpr(const CallNode *call_node) {
160	    if (!call_node || call_node->op != tir::builtin::call_extern()) {
161	      return "";
162	    }
163	
164	    if (call_node->args.empty() || !call_node->args[0].as<StringImmNode>()) {
165	      return "";
166	    }
167	    std::string copy_stmt = Downcast<StringImm>(call_node->args[0])->value;
168	    for (const auto &target_substr : target_copy_stmts_) {
169	      size_t pos = copy_stmt.find(target_substr);
170	      if (pos != std::string::npos) {
171	        return copy_stmt;
172	      }
173	    }
174	    return "";
175	  }
176	
177	  std::pair<const CallNode *, const CallNode *>
178	  ExtractCopyAccessPtrs(const CallNode *call_node) {
179	    Array<PrimExpr> call_node_args = call_node->args;
180	    const CallNode *src_ptr = call_node_args[1].as<CallNode>();
181	    const CallNode *dst_ptr = call_node_args[2].as<CallNode>();
182	    ICHECK(src_ptr != nullptr && dst_ptr != nullptr)
183	        << "[Error]<WorkspaceReduction>: src_ptr or dst_ptr is "
184	           "nullptr!";
185	    ICHECK(src_ptr->op.same_as(tvm::tir::builtin::tvm_access_ptr()) &&
186	           src_ptr->args.size() >= 2)
187	        << "[Error]<WorkspaceReduction>: src is not access ptr or "
188	           "its size of args is too small";
189	    ICHECK(dst_ptr->op.same_as(tvm::tir::builtin::tvm_access_ptr()) &&
190	           dst_ptr->args.size() >= 2)
191	        << "[Error]<WorkspaceReduction>: dst is not access ptr or "
192	           "its size of args is too small";
193	    return {src_ptr, dst_ptr};
194	  }
195	
196	  std::vector<std::string> ParseTemplateParams(const std::string &func_name) {
197	    std::vector<std::string> params;
198	    size_t left = func_name.find('<');
199	    size_t right = func_name.rfind('>');
200	    ICHECK(left != std::string::npos && right != std::string::npos &&
201	           left < right)
202	        << "[Error]<WorkspaceReduction>: illegal template parameters scope!";
203	    std::string content = func_name.substr(left + 1, right - left - 1);
204	    std::string current;
205	    for (auto &c : content) {
206	      if (c == ',') {
207	        ICHECK(!current.empty()) << "[Error]<WorkspaceReduction>: Empty "
208	                                    "parameter found in template!";
209	        params.push_back(current); // [type N M] or
210	                                   // [type1 type2 LayoutGM M N enRelu]
211	        current = "";
212	        continue;
213	      }
214	      if (!std::isspace(c))
215	        current.push_back(c);
216	    }
217	    ICHECK(!current.empty())
218	        << "[Error]<WorkspaceReduction>: Empty parameter found in template!";
219	    params.push_back(current);
220	    return params;
221	  }
222	
223	  CrossCoreCopyInfo CrossCoreCopyInfoCollector(
224	      const std::string &copy_stmt_name, const CallNode *call_node,
225	      const CallNode *src_access_ptr, const CallNode *dst_access_ptr) {
226	    const VarNode *src_name_var_node = (src_access_ptr->args[1].as<VarNode>());
227	    const VarNode *dst_name_var_node = (dst_access_ptr->args[1].as<VarNode>());
228	    ICHECK(src_name_var_node != nullptr && dst_name_var_node != nullptr)
229	        << "[Error]<WorkspaceReduction>: src or dst args[1] is not VarNode!";
230	
231	    CrossCoreCopyInfo copy_info;
232	    copy_info.copy_stmt_name = copy_stmt_name;
233	    copy_info.src_buffer_name = src_name_var_node->name_hint;
234	    copy_info.dst_buffer_name = dst_name_var_node->name_hint;
235	
236	    copy_info.params = ParseTemplateParams(copy_stmt_name);
237	
238	    if (copy_stmt_name.find("copy_ub_to_l1") != std::string::npos) {
239	      ICHECK(copy_info.params.size() >= 2)
240	          << "[Error]<WorkspaceReduction> PTO: copy_ub_to_l1 template expects "
241	             "2+ params, got "
242	          << copy_info.params.size();
243	      copy_info.direction = CopyDirection::UbToL1;
244	      copy_info.dtype_str =
245	          copy_info.params[0]; // UbToL1: [dtype, N, M] or [dtype, N]
246	
247	      if (copy_info.params.size() >= 3) {
248	        // Normal UbToL1: [dtype, N, M] -> swap to [dtype, M, N]
249	        std::swap(copy_info.params[1], copy_info.params[2]);
250	        int M = std::stoi(copy_info.params[1]);
251	        int N = std::stoi(copy_info.params[2]);
252	        if (context_.core_meta_info_.vid_var.defined() &&
253	            context_.core_meta_info_.vector_cnt > 1) {
254	          M *= context_.core_meta_info_.vector_cnt;
255	        }
256	        copy_info.shapes.push_back(IntImm(DataType::Int(32), M));
257	        copy_info.shapes.push_back(IntImm(DataType::Int(32), N));
258	        copy_info.per_block_ele_nums = M * N;
259	      } else {
260	        // UbToL1 with 2 params: [dtype, N]
261	        int N = std::stoi(copy_info.params[1]);
262	        copy_info.shapes.push_back(IntImm(DataType::Int(32), N));
263	        copy_info.per_block_ele_nums = N;
264	      }
265	    } else {
266	      ICHECK(copy_info.params.size() >= 5)
267	          << "[Error]<WorkspaceReduction> PTO: copy_l0c_to_ub template expects "
268	             "5+ params, got "
269	          << copy_info.params.size();
270	      copy_info.direction = CopyDirection::L0cToUb;
271	      copy_info.dtype_str =
272	          copy_info.params[1]; // L0cToUb: [src_dtype, dst_dtype,
273	                               // LayoutGM, M, N, enRelu]
274	
275	      int M = std::stoi(copy_info.params[3]);
276	      int N = std::stoi(copy_info.params[4]);
277	      copy_info.shapes.push_back(IntImm(DataType::Int(32), M));
278	      copy_info.shapes.push_back(IntImm(DataType::Int(32), N));
279	      copy_info.per_block_ele_nums = M * N;
280	    }
281	
282	    if (call_node->args.size() >= 7) {
283	      // Read src/dst extents from runtime args (pushed by ascend.cc
284	      // virtual_channel)
285	      auto src_N_imm = call_node->args[3].as<IntImmNode>();
286	      auto src_M_imm = call_node->args[4].as<IntImmNode>();
287	      auto dst_M_imm = call_node->args[5].as<IntImmNode>();
288	      auto dst_N_imm = call_node->args[6].as<IntImmNode>();
289	      ICHECK(src_N_imm && src_M_imm && dst_M_imm && dst_N_imm)
290	          << "[Error]<WorkspaceReduction>: virtual_channel args must be "
291	             "IntImm, "
292	          << "got non-IntImm PrimExpr. Dynamic shapes not yet supported.";
293	      copy_info.src_N = src_N_imm->value;
294	      copy_info.src_M = src_M_imm->value;
295	      copy_info.dst_M = dst_M_imm->value;
296	      copy_info.dst_N = dst_N_imm->value;
297	    }
298	
299	    return copy_info;
300	  }
301	
302	  void WorkspaceInfoCollector(const CrossCoreCopyInfo &copy_info,
303	                              const CallNode *dst_access_ptr) {
304	    ICHECK(dst_access_ptr != nullptr)
305	        << "[Error]<WorkspaceReduction>: dst_access_ptr is nullptr!";
306	
307	    ++context_.workspace_num_;
308	    WorkspaceInfo ws_info;
309	    std::stringstream ss;
310	    ss << "workspace_" << context_.workspace_num_;
311	    ws_info.workspace_name = ss.str();
312	    const std::string &src_buffer_name = copy_info.src_buffer_name;
313	    const std::string &dst_buffer_name = copy_info.dst_buffer_name;
314	
315	    ws_info.associated_dst_buffer_name = dst_buffer_name;
316	
317	    // Check if src_buffer is in skip set (must be defined before switch)
318	    bool is_skip_ub =
319	        context_.buffers_skip_vid_reduction_.count(src_buffer_name) > 0;
320	
321	    switch (copy_info.direction) {
322	    case CopyDirection::UbToL1:
323	      ws_info.dtype_str = copy_info.dtype_str;
324	      ws_info.dtype = ConvertStringToDataType(ws_info.dtype_str);
325	
326	      if (is_skip_ub) {
327	        // Skip UB scenario: use full L1 shape from buffer_shapess
328	        // Template params for skip UB: [dtype, size] (no M, N)
329	
330	        // dst_access_ptr args: [type_annotation, var, offset, extent, ...]
331	        // args.size() should be at least 4
332	
333	        // Check args size before accessing
334	        ICHECK(dst_access_ptr->args.size() >= 4)
335	            << "[ERROR]<WorkspaceReduction>: dst_access_ptr args size "
336	               "should be at least 4, got "
337	            << dst_access_ptr->args.size();
338	
339	        PrimExpr dst_offset = dst_access_ptr->args[2]; // row offset
340	
341	        // Get dst buffer full shape from buffer_shapes_
342	        auto shape_it = context_.buffer_shapes_.find(dst_buffer_name);
343	        ICHECK(shape_it != context_.buffer_shapes_.end())
344	            << "[ERROR]<WorkspaceReduction>: dst_buffer " << dst_buffer_name
345	            << " not found in buffer_shapes_";
346	        Array<PrimExpr> dst_full_shape = shape_it->second;
347	
348	        // Shape must be 2D [M, N] for current Skip UB UbToL1 scenario
349	        // Future: Extend to support multi-dimensional shapes based on
350	        // buffer scope
351	        ICHECK(dst_full_shape.size() == 2)
352	            << "[ERROR]<WorkspaceReduction>: Skip UB UbToL1 expects "
353	               "dst_full_shape to be 2D, "
354	               "got "
355	            << dst_full_shape.size();
356	
357	        PrimExpr M = dst_full_shape[0]; // rows
358	        PrimExpr N = dst_full_shape[1]; // cols
359	
360	        ws_info.shapes.push_back(M);
361	        ws_info.shapes.push_back(N);
362	
363	        // per_block_ele_nums = M * N
364	        int64_t M_val = 0, N_val = 0;
365	        if (const IntImmNode *M_imm = M.as<IntImmNode>()) {
366	          M_val = M_imm->value;
367	        }
368	        if (const IntImmNode *N_imm = N.as<IntImmNode>()) {
369	          N_val = N_imm->value;
370	        }
371	        ws_info.per_block_ele_nums = M_val * N_val;
372	
373	        // dst_extent for workspace = M * N (full L1 size)
374	        PrimExpr dst_full_extent = M * N;
375	
376	        // base offset: cid * dst_full_extent (for workspace declaration,
377	        // excludes dst_offset) workspace declaration)
378	        ws_info.offset = context_.core_meta_info_.cid_var * dst_full_extent;
379	
380	        // Store row offset separately, added during UbToL1 in-place
381	        // transform
382	        ws_info.dst_l1_row_offset = dst_offset;
383	
384	        // extent: total_core_nums * dst_full_extent - base_offset
385	        ws_info.extent =
386	            context_.core_meta_info_.total_core_nums * dst_full_extent -
387	            ws_info.offset;
388	
389	      } else {
390	        // Normal UB scenario: use shapes from copy_info
391	        ws_info.shapes = copy_info.shapes;
392	        ws_info.per_block_ele_nums = copy_info.per_block_ele_nums;
393	
394	        ws_info.offset = context_.core_meta_info_.cid_var *
395	                         IntImm(DataType::Int(64), ws_info.per_block_ele_nums);
396	
397	        ws_info.extent =
398	            context_.core_meta_info_.total_core_nums *
399	                IntImm(DataType::Int(64), ws_info.per_block_ele_nums) -
400	            ws_info.offset;
401	      }
402	      break;
403	    case CopyDirection::L0cToUb:
404	      ws_info.dtype_str =
405	          copy_info.dtype_str; // L0cToUb: [src_dtype, dst_dtype,
406	                               // LayoutGM, M, N, enRelu]
407	      ws_info.dtype = ConvertStringToDataType(ws_info.dtype_str);
408	      ws_info.shapes = copy_info.shapes;
409	      ws_info.per_block_ele_nums = copy_info.per_block_ele_nums;
410	
411	      ws_info.offset = context_.core_meta_info_.cid_var *
412	                       IntImm(DataType::Int(64), ws_info.per_block_ele_nums);
413	
414	      ws_info.extent =
415	          context_.core_meta_info_.total_core_nums *
416	              IntImm(DataType::Int(64), ws_info.per_block_ele_nums) -
417	          ws_info.offset;
418	      break;
419	    }
420	
421	    Array<PrimExpr> real_shapes;
422	    if (pto_use_pipe_) {
423	      // A2 PTO: flat 1D buffer with 2x size for FIFO double-buffering
424	      PrimExpr total_elems = context_.core_meta_info_.total_core_nums;
425	      for (const auto &shape : ws_info.shapes) {
426	        total_elems = total_elems * shape;
427	      }
428	      total_elems = total_elems * IntImm(DataType::Int(64), 2);
429	      real_shapes.push_back(total_elems);
430	    } else {
431	      real_shapes.push_back(context_.core_meta_info_.total_core_nums);
432	      for (const auto &shape : ws_info.shapes) {
433	        real_shapes.push_back(shape);
434	      }
435	    }
436	    ws_info.dim = IntImm(DataType::Int(64), real_shapes.size());
437	    ws_info.workspace_buffer = decl_buffer(real_shapes, ws_info.dtype,
438	                                           ws_info.workspace_name, "global");
439	
440	    context_.workspace_map_[ws_info.workspace_name] = ws_info;
441	    context_.src_to_workspace_map_[copy_info.src_buffer_name] =
442	        ws_info.workspace_name;
443	    context_.dst_to_workspace_map_[copy_info.dst_buffer_name] =
444	        ws_info.workspace_name;
445	  }
446	
447	  int GetDtypeBytes(const std::string &dtype_str) {
448	    auto it = type_map_.find(dtype_str);
449	    ICHECK(it != type_map_.end())
450	        << "[Error]<WorkspaceReduction> PTO: Unsupported dtype: " << dtype_str;
451	    return it->second.bytes();
452	  }
453	
454	  // Returns:
455	  //   0 = TILE_NO_SPLIT (shapes equal)
456	  //   1 = TILE_UP_DOWN (M differs by 2x)
457	  //   2 = TILE_LEFT_RIGHT (N differs by 2x)
458	  static int ComputeSplitAxis(int src_M, int src_N, int dst_M, int dst_N) {
459	    if (src_M == dst_M && src_N == dst_N)
460	      return 0;
461	    if (src_M * 2 == dst_M || dst_M * 2 == src_M)
462	      return 1;
463	    if (src_N * 2 == dst_N || dst_N * 2 == src_N)
464	      return 2;
465	    return 1;
466	  }
467	
468	  void PipeInfoCollector(const CrossCoreCopyInfo &copy_info,
469	                         const CallNode *call_node) {
470	    const std::string &src_buffer_name = copy_info.src_buffer_name;
471	    const std::string &dst_buffer_name = copy_info.dst_buffer_name;
472	    bool is_ub_to_l1 = (copy_info.direction == CopyDirection::UbToL1);
473	
474	    CopyGlobalContext::PipeInfo info;
475	    if (is_ub_to_l1) {
476	      info.dir_type = 2;
477	      info.op_name = "copy_pipe_to_l1";
478	
479	      // Check if tmp buffer is provided for A5 (ND->Nz conversion)
480	      // After AscendCopy::Lower, args layout: [0]=func_name, [1]=src_ptr,
481	      // [2]=dst_ptr, [3]=srcN, [4]=srcM, [5]=dstM, [6]=dstN, [7]=tmp_ptr,
482	      // [8]=tmpM, [9]=tmpN
483	      if (call_node->args.size() > 9) {
484	        PrimExpr tmp_expr = call_node->args[7];
485	        if (auto *tmp_call = tmp_expr.as<CallNode>()) {
486	          info.has_tmp = true;
487	          info.tmp_M_val = Downcast<IntImm>(call_node->args[8])->value;
488	          info.tmp_N_val = Downcast<IntImm>(call_node->args[9])->value;
489	        }
490	      }
491	    } else {
492	      info.dir_type = 1;
493	      info.op_name = "copy_pipe_to_ub";
494	    }
495	
496	    info.dtype_str = copy_info.dtype_str;
497	    info.src_N_val = copy_info.src_N;
498	    info.src_M_val = copy_info.src_M;
499	    info.dst_M_val = copy_info.dst_M;
500	    info.dst_N_val = copy_info.dst_N;
501	
502	    info.flag_id = pipe_flag_id_counter_;
503	    pipe_flag_id_counter_ += 2; // one pipe needs 2 FlagID
504	    int dtype_bytes = GetDtypeBytes(info.dtype_str);
505	    info.slot_size = copy_info.per_block_ele_nums * dtype_bytes;
506	    info.slot_num = 1;
507	    info.pipe_id = "pipe_" + std::to_string(info.flag_id) + "_" +
508	                   (info.dir_type == 2 ? "V2C" : "C2V");
509	    info.split_axis = ComputeSplitAxis(info.src_M_val, info.src_N_val,
510	                                       info.dst_M_val, info.dst_N_val);
511	    info.workspace_name =
512	        needs_gm_workspace_ ? context_.src_to_workspace_map_.at(src_buffer_name)
513	                            : "";
514	    context_.pipe_info_map_[dst_buffer_name] = info;
515	  }
516	
517	  void VisitStmt(const Stmt &stmt) final { StmtExprVisitor::VisitStmt(stmt); }
518	
519	  void VisitStmt_(const EvaluateNode *op) final {
520	    const CallNode *call_node = op->value.as<CallNode>();
521	    if (!call_node) {
522	      return StmtExprVisitor::VisitStmt_(op);
523	    }
524	
525	    std::string copy_stmt_name = IsTargetCopyExpr(call_node);
526	    if (!copy_stmt_name.empty()) {
527	      // Extract copy access ptrs ONCE (shared by workspace collection,
528	      // copy-back tracking, and PTO pipe metadata)
529	      auto [src_ptr, dst_ptr] = ExtractCopyAccessPtrs(call_node);
530	
531	      CrossCoreCopyInfo copy_info = CrossCoreCopyInfoCollector(
532	          copy_stmt_name, call_node, src_ptr, dst_ptr);
533	
534	      // Layer 1: Workspace collection (differs per backend)
535	      // Ascend C || A2 PTO: collect workspace info for GM buffer allocation
536	      // A5 PTO: skip workspace collection
537	      if (needs_gm_workspace_ || !pto_use_pipe_) {
538	        WorkspaceInfoCollector(copy_info, dst_ptr);
539	      }
540	
541	      // Layer 2: Shared copy-back tracking (AscendC + PTO both need this)
542	      const std::string &src_buffer_name = copy_info.src_buffer_name;
543	      const std::string &dst_buffer_name = copy_info.dst_buffer_name;
544	      context_.tracked_buffers_.insert(src_buffer_name);
545	      context_.src_to_dst_map_[src_buffer_name] = dst_buffer_name;
546	
547	      // skip UB + UbToL1: reconstruct dst_access_ptr
548	      bool is_skip_ub =
549	          context_.buffers_skip_vid_reduction_.count(src_buffer_name) > 0;
550	      bool is_ub_to_l1 = (copy_info.direction == CopyDirection::UbToL1);
551	
552	      if (is_skip_ub && is_ub_to_l1) {
553	        // Get dst full shape [M, N] from buffer_shapes_
554	        auto shape_it = context_.buffer_shapes_.find(dst_buffer_name);
555	        if (shape_it != context_.buffer_shapes_.end()) {
556	          Array<PrimExpr> dst_full_shape = shape_it->second;
557	          PrimExpr M = dst_full_shape[0]; // rows
558	          PrimExpr N = dst_full_shape[1]; // cols
559	          PrimExpr full_extent = M * N;
560	
561	          // Construct new dst_access_ptr: offset=0, extent=M*N
562	          Array<PrimExpr> new_args = {
563	              dst_ptr->args[0],             // type_annotation
564	              dst_ptr->args[1],             // var
565	              IntImm(DataType::Int(64), 0), // offset = 0
566	              full_extent,                  // extent = M * N
567	              dst_ptr->args[4]              // rw_mask
568	          };
569	
570	          Call new_dst_access(dst_ptr->dtype, dst_ptr->op, new_args);
571	          context_.dst_to_access_map_[dst_buffer_name] = new_dst_access;
572	        } else {
573	          context_.dst_to_access_map_[dst_buffer_name] = GetRef<Call>(dst_ptr);
574	        }
575	      } else {
576	        context_.dst_to_access_map_[dst_buffer_name] = GetRef<Call>(dst_ptr);
577	      }
578	
579	      std::string copy_func_name =
580	          call_node->args[0].as<StringImmNode>()->value;
581	      for (auto &target_copy_stmt : target_copy_stmts_) {
582	        if (copy_func_name.find(target_copy_stmt) != std::string::npos) {
583	          context_.dst_to_scope_map_[dst_buffer_name] =
584	              scope_table_[target_copy_stmt];
585	        }
586	      }
587	
588	      // Layer 3: PTO pipe metadata collection (for deferred pop emission)
589	      if (pto_use_pipe_) {
590	        PipeInfoCollector(copy_info, call_node);
591	      }
592	    }
593	  }
594	
595	  void VisitStmt_(const AttrStmtNode *op) override {
596	
597	    if (op->attr_key == tvm::tir::attr::thread_extent) {
598	      if (const IterVarNode *iter_var_node = op->node.as<IterVarNode>()) {
599	        IterVar iter_var = GetRef<IterVar>(iter_var_node);
600	        if (/*!context_.core_meta_info_.is_valid &&*/
601	            iter_var->thread_tag == "blockIdx.x") {
602	          context_.core_meta_info_.cid_var = iter_var->var;
603	          context_.core_meta_info_.total_core_nums = op->value;
604	          // context_.core_meta_info_.is_valid = true;
605	        }
606	        if (iter_var->thread_tag == "threadIdx.x") {
607	          context_.core_meta_info_.vid_var = iter_var->var;
608	          context_.core_meta_info_.vector_cnt =
609	              Downcast<IntImm>(op->value)->value; // 1 or 2
610	        }
611	        if (iter_var->thread_tag == "blockIdx.y") {
612	          context_.core_meta_info_.vid_var = iter_var->var;
613	          context_.core_meta_info_.vector_cnt =
614	              Downcast<IntImm>(op->value)->value; // 2
615	        }
616	      }
617	    }
618	
619	    StmtVisitor::VisitStmt_(op);
620	  }
