643	// ============================================================================
644	// Free Pipe Auto-Insertion: Buffer access-order tracking and free_pipe
645	// insertion
646	//
647	// For each copy-from-pipe (copy_pipe_to_l1, copy_pipe_to_ub,
648	// copy_pipe_to_ub_V), inserts an ascend_free_pipe_C or ascend_free_pipe_V
649	// call at the correct position based on buffer lifecycle analysis.
650	//
651	// Algorithm per SeqStmt scope:
652	//   1. Find each copy-from-pipe call and its target buffer
653	//   2. Scan forward for the first subsequent write to that buffer
654	//   3. Before that write, find the last access (read or write)
655	//   4. Insert free_pipe after that last access
656	//   5. If no subsequent write, insert after the last access overall
657	// ============================================================================
658	
659	// Collects per-buffer {has_read, has_write} in one AST pass.
660	// filter=nullptr means collect all; non-null restricts to named buffers.
661	struct AccessInfo {
662	  bool has_read = false;
663	  bool has_write = false;
664	};
665	
666	class BufferAccessCollector : public StmtExprVisitor {
667	public:
668	  const std::unordered_set<std::string> *filter;
669	  std::unordered_map<std::string, AccessInfo> accesses;
670	
671	  explicit BufferAccessCollector(
672	      const std::unordered_set<std::string> *f = nullptr)
673	      : filter(f) {}
674	
675	  void VisitExpr_(const BufferLoadNode *op) final {
676	    const std::string &name = op->buffer->name;
677	    if (!filter || filter->count(name)) {
678	      accesses[name].has_read = true;
679	    }
680	    StmtExprVisitor::VisitExpr_(op);
681	  }
682	
683	  void VisitStmt_(const BufferStoreNode *op) final {
684	    const std::string &name = op->buffer->name;
685	    if (!filter || filter->count(name)) {
686	      accesses[name].has_write = true;
687	    }
688	    StmtExprVisitor::VisitStmt_(op);
689	  }
690	
691	  void VisitExpr_(const CallNode *op) final {
692	    for (const auto &arg : op->args) {
693	      const CallNode *access_ptr = arg.as<CallNode>();
694	      if (!access_ptr ||
695	          !access_ptr->op.same_as(tir::builtin::tvm_access_ptr())) {
696	        continue;
697	      }
698	      if (access_ptr->args.size() >= 5) {
699	        const VarNode *var = access_ptr->args[1].as<VarNode>();
700	        if (!var)
701	          continue;
702	        const std::string &name = var->name_hint;
703	        if (filter && !filter->count(name))
704	          continue;
705	        int rw_mask = Downcast<IntImm>(access_ptr->args[4])->value;
706	        auto &info = accesses[name];
707	        if (rw_mask & 1)
708	          info.has_read = true;
709	        if (rw_mask & 2)
710	          info.has_write = true;
711	      }
712	    }
713	    StmtExprVisitor::VisitExpr_(op);
714	  }
715	};
716	
717	// Mutator that inserts ascend_free_pipe_C/V calls after copy-from-pipes
718	// (copy_pipe_to_l1 / copy_pipe_to_ub / copy_pipe_to_ub_V) buffer data has
719	// been consumed.  Analysis is scoped to each SeqStmt; free_pipe never crosses
720	// ForNode or IfThenElse boundaries.
721	class FreePipeInserter : public StmtMutator {
722	private:
723	  // Check if a single Evaluate node is a copy-from-pipe call.
724	  // Returns true if found, populating out params.
725	  bool CheckEvaluateForCopyFromPipe(const Stmt &stmt, std::string &out_buffer,
726	                                    int &out_flag_id, bool &out_is_cube) {
727	    const EvaluateNode *eval = stmt.as<EvaluateNode>();
728	    if (!eval)
729	      return false;
730	    const CallNode *call = eval->value.as<CallNode>();
731	    if (!call || call->op != tir::builtin::call_extern())
732	      return false;
733	    if (call->args.size() < 4 || !call->args[0].as<StringImmNode>())
734	      return false;
735	
736	    std::string func_name = Downcast<StringImm>(call->args[0])->value;
737	    // Match copy-from-pipes: copy_pipe_to_l1, copy_pipe_to_ub,
738	    // copy_pipe_to_ub_V
739	    bool is_l1 = (func_name.find("copy_pipe_to_l1") != std::string::npos);
740	    bool is_ub = (func_name.find("copy_pipe_to_ub") != std::string::npos);
741	    if (!is_l1 && !is_ub)
742	      return false;
743	
744	    // Extract target buffer from access_ptr (args[1])
745	    const CallNode *access_ptr = call->args[1].as<CallNode>();
746	    if (!access_ptr ||
747	        !access_ptr->op.same_as(tir::builtin::tvm_access_ptr())) {
748	      return false;
749	    }
750	    if (access_ptr->args.size() < 2)
751	      return false;
752	    const VarNode *var = access_ptr->args[1].as<VarNode>();
753	    if (!var)
754	      return false;
755	
756	    out_buffer = var->name_hint;
757	    out_flag_id = Downcast<IntImm>(call->args[3])->value;
758	    out_is_cube = is_l1; // L1 target -> free_pipe_C, UB -> free_pipe_V
759	    return true;
760	  }
761	
762	  // Detect copy-from-pipes in a statement, looking one level into nested
763	  // SeqStmt (VisitStmt_ wraps pipe op + orig_stmt in a SeqStmt).
764	  bool DetectCopyFromPipe(const Stmt &stmt, std::string &out_buffer,
765	                          int &out_flag_id, bool &out_is_cube) {
766	    // Direct Evaluate node
767	    if (CheckEvaluateForCopyFromPipe(stmt, out_buffer, out_flag_id,
768	                                     out_is_cube)) {
769	      return true;
770	    }
771	    // Check inside one level of SeqStmt (the wrapper created by VisitStmt_)
772	    if (const SeqStmtNode *seq = stmt.as<SeqStmtNode>()) {
773	      for (const auto &child : seq->seq) {
774	        if (CheckEvaluateForCopyFromPipe(child, out_buffer, out_flag_id,
775	                                         out_is_cube)) {
776	          return true;
777	        }
778	      }
779	    }
780	    return false;
781	  }
782	
783	  // Generate free_pipe Evaluate node using registered op:
784	  //   Evaluate(Call(tl.ascend_free_pipe, {StringImm("free_pipe_C/V"),
785	  //   IntImm(flag_id)}))
786	  Stmt MakeFreePipe(bool is_cube, int flag_id) {
787	    std::string scope_hint = is_cube ? "free_pipe_C" : "free_pipe_V";
788	    return Evaluate(
789	        Call(DataType::Int(32), tl::ascend_free_pipe(),
790	             {StringImm(scope_hint), IntImm(DataType::Int(32), flag_id)}));
791	  }
792	
793	public:
794	  Stmt VisitStmt_(const SeqStmtNode *op) final {
795	    // First, recursively visit all children to handle nested structures
796	    Array<Stmt> visited_children;
797	    for (const auto &child : op->seq) {
798	      visited_children.push_back(StmtMutator::VisitStmt(child));
799	    }
800	
801	    // Collect copy-from-pipe info from each child position, and gather target
802	    // buffer names for filtered pre-scan.
803	    struct CopyFromPipeEntry {
804	      int pos;
805	      std::string buffer;
806	      int flag_id;
807	      bool is_cube;
808	    };
809	    std::vector<CopyFromPipeEntry> copy_from_pipe_entries;
810	    std::unordered_set<std::string> target_buffers;
811	
812	    for (int i = 0; i < static_cast<int>(visited_children.size()); ++i) {
813	      std::string buf;
814	      int fid = 0;
815	      bool is_cube = false;
816	      if (DetectCopyFromPipe(visited_children[i], buf, fid, is_cube)) {
817	        copy_from_pipe_entries.push_back({i, buf, fid, is_cube});
818	        target_buffers.insert(buf);
819	      }
820	    }
821	
822	    if (copy_from_pipe_entries.empty()) {
823	      return SeqStmt(visited_children);
824	    }
825	
826	    // Pre-scan: build access table for target buffers only (one pass).
827	    std::vector<std::unordered_map<std::string, AccessInfo>> access_table(
828	        visited_children.size());
829	    for (int i = 0; i < static_cast<int>(visited_children.size()); ++i) {
830	      BufferAccessCollector collector(&target_buffers);
831	      collector(visited_children[i]);
832	      access_table[i] = std::move(collector.accesses);
833	    }
834	
835	    // For each copy-from-pipe, look up the pre-built table to find free_pipe
836	    // insertion point: last access before first subsequent write, or last
837	    // access overall if no subsequent write exists.
838	    std::unordered_map<int, std::vector<Stmt>> pos_to_free_pipe;
839	
840	    for (const auto &entry : copy_from_pipe_entries) {
841	      int entry_pos = entry.pos;
842	      const std::string &target_buf = entry.buffer;
843	
844	      int first_write_pos = -1;
845	      int last_access_pos = -1;
846	
847	      for (int j = entry_pos + 1; j < static_cast<int>(visited_children.size());
848	           ++j) {
849	        auto it = access_table[j].find(target_buf);
850	        if (it == access_table[j].end())
851	          continue;
852	
853	        if (first_write_pos == -1 && it->second.has_write) {
854	          first_write_pos = j;
855	          break;
856	        }
857	        last_access_pos = j;
858	      }
859	
860	      int insert_after = (last_access_pos != -1) ? last_access_pos : entry_pos;
861	
862	      pos_to_free_pipe[insert_after].push_back(
863	          MakeFreePipe(entry.is_cube, entry.flag_id));
864	    }
865	
866	    // Build result array with free_pipe insertions
867	    Array<Stmt> result;
868	    for (int i = 0; i < static_cast<int>(visited_children.size()); ++i) {
869	      result.push_back(visited_children[i]);
870	      auto it = pos_to_free_pipe.find(i);
871	      if (it != pos_to_free_pipe.end()) {
872	        for (const auto &free_pipe : it->second) {
873	          result.push_back(free_pipe);
874	        }
875	      }
876	    }
877	
878	    return SeqStmt(result);
879	  }
880	};
