882	class AscendWorkspaceReductionPass : public arith::IRMutatorWithAnalyzer {
883	public:
884	  static PrimFunc Substitute(PrimFunc f, bool pto_use_pipe = false,
885	                             const std::string &platform = "A3") {
886	    arith::Analyzer analyzer;
887	
888	    // Read buffers_skip_vid_reduction from PrimFunc attrs
889	    std::unordered_set<std::string> skip_buffer_names;
890	    std::unordered_map<std::string, Array<PrimExpr>> buffer_shapes;
891	    if (f->attrs.defined()) {
892	      auto attrs_dict = f->attrs->dict;
893	
894	      // Read buffers_skip_vid_reduction
895	      auto it_skip = attrs_dict.find("buffers_skip_vid_reduction");
896	      if (it_skip != attrs_dict.end()) {
897	        auto skip_array = Downcast<Array<String>>((*it_skip).second);
898	        for (const auto &name : skip_array) {
899	          skip_buffer_names.insert(name);
900	        }
901	      }
902	
903	      // Read buffer_shapess for skip UB scenario
904	      auto it_shapes = attrs_dict.find("buffer_shapess");
905	      if (it_shapes != attrs_dict.end()) {
906	        auto shapes_map =
907	            Downcast<Map<Var, Array<PrimExpr>>>((*it_shapes).second);
908	        for (const auto &pair : shapes_map) {
909	          std::string buf_name = pair.first->name_hint;
910	          buffer_shapes[buf_name] = pair.second;
911	        }
912	      }
913	    }
914	
915	    CopyInfoCollector info_collector({}, {}, pto_use_pipe, platform);
916	    info_collector.SetSkipBuffers(skip_buffer_names);
917	    info_collector.SetBufferShapes(buffer_shapes);
918	    info_collector.VisitStmt(f->body);
919	    const CopyGlobalContext &context = info_collector.GetCopyGlobalContext();
920	    AscendWorkspaceReductionPass substituter(&analyzer, context, pto_use_pipe,
921	                                             platform);
922	
923	    auto *f_mut = f.CopyOnWrite();
924	    f_mut->body = substituter.VisitStmt(f->body);
925	
926	    // free_pipe auto-insertion: after copy-from-pipe buffer data is consumed
927	    if (pto_use_pipe && !context.pipe_info_map_.empty()) {
928	      FreePipeInserter free_pipe_inserter;
929	      f_mut->body = free_pipe_inserter(f_mut->body);
930	    }
931	
932	    Array<Var> new_params = f_mut->params;
933	    Array<IntImm> auto_gm_idx;
934	    for (const auto &[ws_name, ws_info] : context.workspace_map_) {
935	      if (ws_info.workspace_buffer.defined()) {
936	        Var ws_handle(ws_name + "_handle", DataType::Handle());
937	        if (!f_mut->buffer_map.count(ws_handle)) {
938	          f_mut->buffer_map.Set(ws_handle, ws_info.workspace_buffer);
939	          new_params.push_back(ws_handle);
940	          auto_gm_idx.push_back(
941	              IntImm(DataType::UInt(32), new_params.size() - 1));
942	        }
943	      }
944	    }
945	
946	    f_mut->params = new_params;
947	    tvm::tir::PrimFunc prim_func_with_new_attr =
948	        GetRef<tvm::tir::PrimFunc>(f_mut);
949	    prim_func_with_new_attr = tvm::WithAttr(std::move(prim_func_with_new_attr),
950	                                            "auto_gm_indices", auto_gm_idx);
951	
952	    // Serialize pipe metadata as PrimFunc attr for codegen access
953	    if (pto_use_pipe && !context.pipe_info_map_.empty()) {
954	      Map<IntImm, Map<String, ObjectRef>> pipe_infos;
955	      for (const auto &[dst_buf_name, info] : context.pipe_info_map_) {
956	        Map<String, ObjectRef> fields;
957	        fields.Set("flag_id", IntImm(DataType::Int(32), info.flag_id));
958	        fields.Set("dir_type", IntImm(DataType::Int(32), info.dir_type));
959	        fields.Set("slot_size", IntImm(DataType::Int(32), info.slot_size));
960	        fields.Set("slot_num", IntImm(DataType::Int(32), info.slot_num));
961	        fields.Set("pipe_id", String(info.pipe_id));
962	        fields.Set("op_name", String(info.op_name));
963	        fields.Set("dtype_str", String(info.dtype_str));
964	        fields.Set("src_M_val", IntImm(DataType::Int(32), info.src_M_val));
965	        fields.Set("src_N_val", IntImm(DataType::Int(32), info.src_N_val));
966	        fields.Set("dst_M_val", IntImm(DataType::Int(32), info.dst_M_val));
967	        fields.Set("dst_N_val", IntImm(DataType::Int(32), info.dst_N_val));
968	        fields.Set("split_axis", IntImm(DataType::Int(32), info.split_axis));
969	        fields.Set("workspace_name", String(info.workspace_name));
970	        fields.Set("has_tmp", IntImm(DataType::Int(32), info.has_tmp ? 1 : 0));
971	        fields.Set("tmp_M_val", IntImm(DataType::Int(32), info.tmp_M_val));
972	        fields.Set("tmp_N_val", IntImm(DataType::Int(32), info.tmp_N_val));
973	        pipe_infos.Set(IntImm(DataType::Int(32), info.flag_id), fields);
974	      }
975	      prim_func_with_new_attr = WithAttr(std::move(prim_func_with_new_attr),
976	                                         "pipe_infos", pipe_infos);
977	    }
978	
979	    return prim_func_with_new_attr;
980	  }
