982	private:
983	  AscendWorkspaceReductionPass(arith::Analyzer *analyzer,
984	                               const CopyGlobalContext &context,
985	                               bool pto_use_pipe = false,
986	                               const std::string &platform = "A3")
987	      : arith::IRMutatorWithAnalyzer(analyzer), context_(context),
988	        core_meta_info__(context.core_meta_info_), pto_use_pipe_(pto_use_pipe),
989	        platform_(platform) {}
990	
991	  const CopyGlobalContext &context_;
992	  const CoreMetaInfo core_meta_info__; // For vid offset calculation
993	  bool pto_use_pipe_;
994	  std::string platform_;
995	
996	  std::unordered_set<std::string> inserted_buffers_;
997	
998	  std::unordered_set<std::string> copy_stmt_table_ = {
999	      "copy_gm_to_l1",  "copy_l1_to_l0a", "copy_l1_to_l0b",
1000	      "copy_l0c_to_gm", "copy_gm_to_ub",  "copy_ub_to_gm",
1001	      "copy_ub_to_l1",  "copy_l0c_to_ub", "copy_ub_to_ub"};
1002	
1003	  std::unordered_map<std::string, std::string> copy_replace_table_ = {
1004	      {"copy_ub_to_l1", "copy_ub_to_gm"}, {"copy_l0c_to_ub", "copy_l0c_to_gm"}};
1005	
1006	  Stmt GenerateCopyToPipe(const CallNode *orig_call,
1007	                          const std::string &func_name_str) {
1008	    Array<PrimExpr> orig_args = orig_call->args;
1009	    PrimExpr src_access = orig_args[1];
1010	    PrimExpr dst_access = orig_args[2];
1011	
1012	    // Get dst buffer name for pipe_info_map_ lookup
1013	    const CallNode *dst_access_ptr = dst_access.as<CallNode>();
1014	    ICHECK(dst_access_ptr && dst_access_ptr->args.size() >= 2);
1015	    const VarNode *dst_var = dst_access_ptr->args[1].as<VarNode>();
1016	    ICHECK(dst_var);
1017	    std::string dst_buffer_name = dst_var->name_hint;
1018	
1019	    auto pipe_it = context_.pipe_info_map_.find(dst_buffer_name);
1020	    ICHECK(pipe_it != context_.pipe_info_map_.end())
1021	        << "[Error]<WorkspaceReduction> PTO: No pipe info found for: "
1022	        << dst_buffer_name;
1023	    const auto &pipe = pipe_it->second;
1024	
1025	    bool is_ub_to_l1 =
1026	        (func_name_str.find("copy_ub_to_l1") != std::string::npos);
1027	    std::string pipe_op1 = is_ub_to_l1 ? "copy_ub_to_pipe" : "copy_l0c_to_pipe";
1028	
1029	    std::stringstream ss;
1030	    ss << "tl::ascend::" << pipe_op1;
1031	    Array<PrimExpr> args = {StringImm(ss.str()), src_access, src_access,
1032	                            IntImm(DataType::Int(32), pipe.flag_id)};
1033	    if (is_ub_to_l1 && pipe.has_tmp && orig_args.size() > 7) {
1034	      PrimExpr tmp_expr = orig_args[7];
1035	      if (tmp_expr.as<CallNode>()) {
1036	        args.push_back(tmp_expr);
1037	      }
1038	    }
1039	    Call call(DataType::Handle(), tir::builtin::call_extern(), args);
1040	
1041	    if (is_ub_to_l1 && pipe.has_tmp && platform_ == "A5" &&
1042	        orig_args.size() > 7 && orig_args[7].as<CallNode>()) {
1043	      Array<PrimExpr> args_nz = {StringImm("tl::ascend::copy_ub_to_ub_Nz"),
1044	                                 src_access, orig_args[7]};
1045	      Call call_nz(DataType::Handle(), tir::builtin::call_extern(), args_nz);
1046	      return SeqStmt({Evaluate(call_nz), Evaluate(call)});
1047	    }
1048	
1049	    return Evaluate(call);
1050	  }
