1053	                            const Call &dst_access) {
1054	    std::string op_name = pipe.op_name;
1055	    if (platform_ == "A5" && op_name == "copy_pipe_to_ub") {
1056	      op_name = "copy_pipe_to_ub_V";
1057	    }
1058	    std::stringstream ss;
1059	    ss << "tl::ascend::" << op_name;
1060	
1061	    Array<PrimExpr> args = {StringImm(ss.str()), dst_access, dst_access,
1062	                            IntImm(DataType::Int(32), pipe.flag_id)};
