1080	  bool IsTargetCopyExpr(const CallNode *call_node) {
1081	
1082	    if (!call_node || call_node->op != tir::builtin::call_extern()) {
1083	      return false;
1084	    }
1085	
1086	    if (call_node->args.empty() || !call_node->args[0].as<StringImmNode>()) {
1087	      return false;
1088	    }
1089	    std::string func_name = Downcast<StringImm>(call_node->args[0])->value;
1090	    for (const auto &[target_substr, replace_substr] : copy_replace_table_) {
1091	      size_t pos = func_name.find(target_substr);
1092	      if (pos != std::string::npos) {
1093	        return true;
1094	      }
1095	    }
1096	    return false;
1097	  }
1098	
1099	  StringImm ReplaceCopyFuncName(const StringImm &orig_name) {
1100	    std::string new_name = orig_name->value;
1101	    std::string original_name = new_name;
1102	
1103	    for (const auto &[target_substr, replace_substr] : copy_replace_table_) {
1104	      size_t pos = new_name.find(target_substr);
1105	      if (pos != std::string::npos) {
1106	        new_name.replace(pos, target_substr.length(), replace_substr);
1107	        break;
1108	      }
1109	    }
1110	
1111	    return StringImm(new_name);
1112	  }
