1114	  std::vector<std::string> IsTargetAccessNode(const CallNode *call_node) {
1115	
1116	    static const std::vector<std::string> EMPTY_BUFFER_LIST;
1117	    std::vector<std::string> dst_buffers_vec;
1118	    if (!call_node) {
1119	      return EMPTY_BUFFER_LIST;
1120	    }
1121	
1122	    if (call_node->args.empty()) {
1123	      return EMPTY_BUFFER_LIST;
1124	    }
1125	
1126	    Array<PrimExpr> call_node_args = call_node->args;
1127	    if (call_node_args.empty()) {
1128	      return EMPTY_BUFFER_LIST;
1129	    }
1130	
1131	    for (int i = 0; i < call_node_args.size(); ++i) {
1132	      const PrimExpr &arg = call_node_args[i];
1133	      const CallNode *access_ptr = arg.as<CallNode>();
1134	
1135	      if (!access_ptr || !access_ptr->op.same_as(builtin::tvm_access_ptr())) {
1136	        continue;
1137	      }
1138	
1139	      Array<PrimExpr> access_args = access_ptr->args;
1140	      ICHECK(!access_args.empty())
1141	          << "[Error]<WorkspaceReduction>: access ptr args is empty!";
1142	      ICHECK(access_args.size() >= 2)
1143	          << "[Error]<WorkspaceReduction>: access ptr args size too small!";
1144	
1145	      const VarNode *buffer_var = access_args[1].as<VarNode>();
1146	      ICHECK(buffer_var != nullptr)
1147	          << "[Error]<WorkspaceReduction>: access ptr args[1] is not VarNode!";
1148	
1149	      std::string buffer_name = buffer_var->name_hint;
1150	
1151	      // access_args layout: [type_annotation, var, offset, extent, rw_mask]
1152	      // Only consider buffer as a "consumer" if rw_mask has read bit set.
1153	      // Skip write-only access (rw_mask == 2) since no copy-back needed before
1154	      // a write.
1155	      ICHECK(access_args.size() >= 5) << "[Error]<WorkspaceReduction>: access "
1156	                                         "ptr args size too small for rw_mask!";
1157	      int rw_mask = Downcast<IntImm>(access_args[4])->value;
1158	      if (!(rw_mask & 1)) {
1159	        // write-only access → this buffer is a producer, not a consumer
1160	        continue;
1161	      }
1162	
1163	      for (const auto &[src_buffer_name, dst_buffer_name] :
1164	           context_.src_to_dst_map_) {
1165	        if (!inserted_buffers_.count(buffer_name) &&
1166	            buffer_name == dst_buffer_name) {
1167	          dst_buffers_vec.push_back(buffer_name);
1168	          inserted_buffers_.insert(buffer_name);
1169	        } else if (inserted_buffers_.count(buffer_name) &&
1170	                   buffer_name == dst_buffer_name) {
1171	          continue;
1172	        }
1173	      }
1174	    }
1175	    return dst_buffers_vec;
1176	  }
1177	
1178	  Call CreateWorkspaceAccessPtr(const WorkspaceInfo &ws_info, int rw_mask,
1179	                                bool other_side_is_ub) {
1180	    DataType dtype = DataType::Handle();
1181	    const Op &op = builtin::tvm_access_ptr();
1182	
1183	    PrimExpr offset = ws_info.offset; // Base offset: cid * M * N
1184	
1185	    // skip UB UbToL1 in-place: add row offset
1186	    // Condition: dst_l1_row_offset exists and workspace as dst (rw_mask=2,
1187	    // write) workspace restore (rw_mask=1, read) doesn't need this
1188	    if (ws_info.dst_l1_row_offset.defined() && rw_mask == 2) {
1189	      offset = offset + ws_info.dst_l1_row_offset;
1190	    }
1191	
1192	    // Check if vid offset needed: GM's other side is UB (UB halved by
1193	    // VidReduction)
1194	    bool need_vid_offset = other_side_is_ub &&
1195	                           core_meta_info__.vid_var.defined() &&
1196	                           core_meta_info__.vector_cnt > 1;
1197	
1198	    if (need_vid_offset) {
1199	      // vid offset: vid * per_block_ele_nums / vector_cnt
1200	      PrimExpr vid_offset =
1201	          core_meta_info__.vid_var *
1202	          IntImm(DataType::Int(64), ws_info.per_block_ele_nums) /
1203	          IntImm(DataType::Int(64), core_meta_info__.vector_cnt);
1204	      offset = offset + vid_offset;
1205	    }
1206	
1207	    Array<PrimExpr> args = {TypeAnnotation(ws_info.dtype),
1208	                            ws_info.workspace_buffer->data, offset,
1209	                            ws_info.extent, IntImm(DataType::Int(32), rw_mask)};
1210	
1211	    Call access_ptr_call(dtype, op, args);
1212	    return access_ptr_call;
1213	  }
1214	
1215	  Stmt CreateGmToDstStmt(const Call &src_access, const Call &dst_access,
1216	                         const DstBufferScope &buffer_scope,
1217	                         PrimExpr &strideN) {
1218	    Array<PrimExpr> args;
1219	    const CallNode *gm_access_ptr = src_access.as<CallNode>();
1220	    const VarNode *gm_var = gm_access_ptr->args[1].as<VarNode>();
1221	    std::string gm_name = gm_var->name_hint;
1222	    WorkspaceInfo ws_info = context_.workspace_map_.at(gm_name);
1223	
1224	    std::stringstream ss;
1225	    ss << "tl::ascend::copy_gm_to_" << PrintDstScope(buffer_scope) << "<"
1226	       << ws_info.dtype_str;
1227	    if (buffer_scope == DstBufferScope::L1) {
1228	      for (auto &shape : ws_info.shapes) {
1229	        // gm_to_l1 : M N
1230	        ss << ", " << shape.as<IntImmNode>()->value;
1231	      }
1232	      ss << ">";
1233	    } else if (buffer_scope == DstBufferScope::Ub) {
1234	      // gm_to_ub: N M (reversed order)
1235	      // threads=2: first dim (M) divided by vector_cnt, each vidcopieshalf
1236	      int idx = 0;
1237	      for (auto it = ws_info.shapes.rbegin(); it != ws_info.shapes.rend();
1238	           ++it, ++idx) {
1239	        int shape_val = (*it).as<IntImmNode>()->value;
1240	        // Last element is original shapes[0] (M), needs division by vector_cnt
1241	        if (idx == ws_info.shapes.size() - 1 &&
1242	            core_meta_info__.vid_var.defined() &&
1243	            core_meta_info__.vector_cnt > 1) {
1244	          shape_val /= core_meta_info__.vector_cnt;
1245	        }
1246	        ss << ", " << shape_val;
1247	      }
1248	      ss << ">";
1249	    }
1250	
1251	    std::string stmt_name_str = ss.str();
1252	
1253	    StringImm stmt_name(stmt_name_str);
1254	    args.push_back(stmt_name);
1255	    args.push_back(src_access);
1256	    args.push_back(dst_access);
1257	    args.push_back(strideN);
1258	
1259	    // Add extra parameters for codegen
1260	    if (buffer_scope == DstBufferScope::L1) {
1261	      // copy_gm_to_l1: add realTailM=0, realTailN=0
1262	      args.push_back(IntImm(DataType::Int(32), 0));
1263	      args.push_back(IntImm(DataType::Int(32), 0));
1264	    } else if (buffer_scope == DstBufferScope::Ub) {
1265	      // copy_gm_to_ub: add maskShapeM, maskShapeN, padValue=0 (full workspace
1266	      // shape, never a tail).
1267	      // ws_info.shapes = [M, N] (workspace shape, M includes vector_cnt)
1268	      // Template params: dstN=N, dstM=M/vector_cnt (from reversed shapes)
1269	      // So maskShapeM=M/vector_cnt, maskShapeN=N
1270	      ICHECK(ws_info.shapes.size() >= 2);
1271	      // Extract M and N from ws_info.shapes
1272	      int M_val = ws_info.shapes[0].as<IntImmNode>()->value;
1273	      int N_val = ws_info.shapes[1].as<IntImmNode>()->value;
1274	      // maskShapeM considers vector_cnt (threads=2 scenario)
1275	      if (core_meta_info__.vid_var.defined() &&
1276	          core_meta_info__.vector_cnt > 1) {
1277	        M_val /= core_meta_info__.vector_cnt;
1278	      }
1279	      args.push_back(IntImm(DataType::Int(32), M_val)); // maskShapeM
1280	      args.push_back(IntImm(DataType::Int(32), N_val)); // maskShapeN
1281	      args.push_back(IntImm(DataType::Int(32), 0));     // padValue
1282	    }
1283	
1284	    Call new_call_node(DataType::Handle(), tvm::tir::builtin::call_extern(),
1285	                       args);
1286	
1287	    return Evaluate(new_call_node);
1288	  }
1289	
1290	  Stmt VisitStmt_(const EvaluateNode *op) final {
1291	    Stmt orig_stmt = arith::IRMutatorWithAnalyzer::VisitStmt_(op);
1292	    const EvaluateNode *orig_eval_node = orig_stmt.as<EvaluateNode>();
1293	    if (!orig_eval_node) {
1294	      return orig_stmt;
1295	    }
1296	
1297	    const CallNode *orig_call = orig_eval_node->value.as<CallNode>();
1298	    if (!orig_call) {
1299	      return orig_stmt;
1300	    }
1301	
1302	    // PTO path: replace cross-core copies with pipe pairs
1303	    if (pto_use_pipe_ && orig_call->op == tir::builtin::call_extern() &&
1304	        orig_call->args.size() > 0 && orig_call->args[0].as<StringImmNode>()) {
1305	      std::string func_name_str =
1306	          Downcast<StringImm>(orig_call->args[0])->value;
1307	      if (func_name_str.find("copy_ub_to_l1") != std::string::npos ||
1308	          func_name_str.find("copy_l0c_to_ub") != std::string::npos) {
1309	        return GenerateCopyToPipe(orig_call, func_name_str);
1310	      }
1311	    }
1312	
1313	    // In-place transform (AscendC path)
1314	    if (IsTargetCopyExpr(orig_call)) {
1315	      // Build new_args from scratch keeping only the first 4 original args.
1316	      // Extra runtime args (src_M/dst_M/dst_N at orig_call->args[4..6])
1317	      // from ascend.cc are dropped here. AscendC codegen expects positional
1318	      // args[3..5] = (count, maskShapeM, maskShapeN) appended via push_back
1319	      // below.
1320	      Array<PrimExpr> new_args;
1321	      new_args.push_back(orig_call->args[0]); // function name string
1322	      new_args.push_back(orig_call->args[1]); // src access_ptr
1323	      new_args.push_back(orig_call->args[2]); // dst access_ptr (replaced below)
1324	      new_args.push_back(
1325	          orig_call
1326	              ->args[3]); // src_N (element count, used as count in codegen)
1327	      StringImm orig_func_name = Downcast<StringImm>(new_args[0]);
1328	      const CallNode *src_access_ptr = new_args[1].as<CallNode>();
1329	      std::string src_buffer_name =
1330	          (src_access_ptr->args[1]).as<VarNode>()->name_hint;
1331	
1332	      // copyA (in-place): GM's other side is source, check if source is UB
1333	      // ub_to_l1 source is UB; l0c_to_ub source is L0C
1334	      std::string orig_func_name_str = orig_func_name->value;
1335	      bool other_side_is_ub =
1336	          (orig_func_name_str.find("copy_ub_to_l1") != std::string::npos);
1337	
1338	      StringImm new_func_name = ReplaceCopyFuncName(orig_func_name);
1339	      new_args.Set(0, new_func_name);
1340	      std::string ws_name = context_.src_to_workspace_map_.at(src_buffer_name);
1341	      WorkspaceInfo ws_info = context_.workspace_map_.at(ws_name);
1342	      new_args.Set(2, CreateWorkspaceAccessPtr(ws_info, 2, other_side_is_ub));
1343	
1344	      // Add extra parameters for codegen
1345	      if (orig_func_name_str.find("copy_ub_to_l1") != std::string::npos) {
1346	        // copy_ub_to_gm: add maskShapeM, maskShapeN
1347	
1348	        // Check if src_buffer is in skip_vid_reduction set
1349	        bool is_skip_ub =
1350	            context_.buffers_skip_vid_reduction_.count(src_buffer_name) > 0;
1351	
1352	        if (is_skip_ub) {
1353	          // Skip UB: use original UB shape from buffer_shapes_
1354	          // These UB buffers not processed by VidReduction, vector split in
1355	          // index array
1356	
1357	          auto shape_it = context_.buffer_shapes_.find(src_buffer_name);
1358	          ICHECK(shape_it != context_.buffer_shapes_.end());
1359	
1360	          // buffer_shapes_ can be 1D [N] or 2D [M, N]
1361	          int M_val = 1; // colsefault value
1362	          int N_val = 1;
1363	          if (shape_it->second.size() >= 1) {
1364	            N_val = shape_it->second[shape_it->second.size() - 1]
1365	                        .as<IntImmNode>()
1366	                        ->value;
1367	          }
1368	          if (shape_it->second.size() >= 2) {
1369	            M_val = shape_it->second[shape_it->second.size() - 2]
1370	                        .as<IntImmNode>()
1371	                        ->value;
1372	          }
1373	
1374	          new_args.push_back(IntImm(DataType::Int(32), M_val)); // maskShapeM
1375	          new_args.push_back(IntImm(DataType::Int(32), N_val)); // maskShapeN
1376	        } else {
1377	          // Normal UB: use ws_info.shapes, considering vector_cnt
1378	          // ws_info.shapes = [M * vector_cnt, N] (workspace stores complete
1379	          // data) maskShapeM = M = ws_info.shapes[0] / vector_cnt (each
1380	          // vidcopieshalf maskShapeN = N = ws_info.shapes[1]
1381	          ICHECK(ws_info.shapes.size() >= 2);
1382	          int M_val = ws_info.shapes[0].as<IntImmNode>()->value;
1383	          int N_val = ws_info.shapes[1].as<IntImmNode>()->value;
1384	          // threads=2: each vidcopies M/vector_cnt
1385	          if (core_meta_info__.vid_var.defined() &&
1386	              core_meta_info__.vector_cnt > 1) {
1387	            M_val /= core_meta_info__.vector_cnt;
1388	          }
1389	          new_args.push_back(IntImm(DataType::Int(32), M_val)); // maskShapeM
1390	          new_args.push_back(IntImm(DataType::Int(32), N_val)); // maskShapeN
1391	        }
1392	      } else if (orig_func_name_str.find("copy_l0c_to_ub") !=
1393	                 std::string::npos) {
1394	        // copy_l0c_to_gm: add realTailM=0, realTailN=0
1395	        new_args.push_back(IntImm(DataType::Int(32), 0));
1396	        new_args.push_back(IntImm(DataType::Int(32), 0));
1397	      }
1398	
1399	      Call new_call =
1400	          Call(orig_call->dtype, orig_call->op, new_args, orig_call->span);
1401	      return Evaluate(new_call);
1402	    }
1403	
1404	    // Insert copy-back statements (for both AscendC and PTO)
1405	    std::vector<std::string> buffer_names_vec = IsTargetAccessNode(orig_call);
1406	    if (buffer_names_vec.empty()) {
1407	      return orig_stmt;
1408	    }
1409	    Array<Stmt> seq_stmts_array;
1410	    for (const auto &buffer_name : buffer_names_vec) {
1411	      if (pto_use_pipe_) {
1412	        // PTO: generate copy_pipe_to_xx from PipeInfo
1413	        auto pipe_it = context_.pipe_info_map_.find(buffer_name);
1414	        ICHECK(pipe_it != context_.pipe_info_map_.end())
1415	            << "[Error]<WorkspaceReduction> PTO: No pipe metadata found for "
1416	               "buffer: "
1417	            << buffer_name;
1418	        seq_stmts_array.push_back(GenerateCopyFromPipe(
1419	            pipe_it->second, context_.dst_to_access_map_.at(buffer_name)));
1420	      } else {
1421	        // AscendC: existing copy_gm_to_dst logic
1422	        auto buffer_scope_it = context_.dst_to_scope_map_.find(buffer_name);
1423	        ICHECK(buffer_scope_it != context_.dst_to_scope_map_.end())
1424	            << "[Error]<WorkspaceReduction>: Dst scope is not found for "
1425	               "buffer: "
1426	            << buffer_name << "\n";
1427	
1428	        DstBufferScope buffer_scope =
1429	            context_.dst_to_scope_map_.at(buffer_name);
1430	        const std::string workspace_name =
1431	            context_.dst_to_workspace_map_.at(buffer_name);
1432	        WorkspaceInfo ws_info = context_.workspace_map_.at(workspace_name);
1433	
1434	        // copyB (copy-back): GM's other side is destination, check if dst is UB
1435	        // gm_to_ub destination is UB; gm_to_l1 destination is L1
1436	        bool other_side_is_ub = (buffer_scope == DstBufferScope::Ub);
1437	        Call workspace_access =
1438	            CreateWorkspaceAccessPtr(ws_info, 1, other_side_is_ub);
1439	        PrimExpr strideN = ws_info.shapes[ws_info.shapes.size() - 1];
1440	        Stmt insert_eval_stmt = this->CreateGmToDstStmt(
1441	            workspace_access, context_.dst_to_access_map_.at(buffer_name),
1442	            buffer_scope, strideN);
1443	        seq_stmts_array.push_back(insert_eval_stmt);
1444	      }
1445	    }
1446	    seq_stmts_array.push_back(orig_stmt);
1447	    return SeqStmt(seq_stmts_array);
1448	  }
