1454	
1455	tvm::transform::Pass AscendWorkspaceReduction() {
1456	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1457	    bool is_pto = false;
1458	    if (auto opt_target = f->GetAttr<Target>(tvm::attr::kTarget)) {
1459	      Target target = opt_target.value();
1460	      if (target->attrs.defined()) {
1461	        auto model_attr = target->attrs.Get("model");
1462	        if (model_attr.defined()) {
1463	          is_pto = (Downcast<String>(model_attr) == "pto");
1464	        }
1465	      }
1466	    }
1467	    std::string platform = "A3";
1468	    auto platform_attr = f->GetAttr<String>("npu_platform");
1469	    if (platform_attr.defined()) {
1470	      platform = platform_attr.value();
1471	    }
1472	    bool use_pipe_config =
1473	        ctx->GetConfig<Bool>(ascendPtoUsePipeInCVCopy, Bool(true)).value();
1474	    bool pto_use_pipe = is_pto && use_pipe_config;
1475	    return AscendWorkspaceReductionPass::Substitute(std::move(f), pto_use_pipe,
1476	                                                    platform);
1477	  };
1478	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendWorkspaceReduction", {});
1479	}
1480	
1481	TVM_REGISTER_GLOBAL("tl.transform.AscendWorkspaceReduction")
1482	    .set_body_typed(AscendWorkspaceReduction);
1483	} // namespace transform
